import { Awaitable, SiteData } from "../shared.js";
import { Router } from "./router.js";
import { App, Component, Ref } from "vue";
//#region src/client/app/theme.d.ts
interface EnhanceAppContext {
  app: App;
  router: Router;
  siteData: Ref<SiteData>;
}
interface Theme {
  Layout?: Component;
  enhanceApp?: (ctx: EnhanceAppContext) => Awaitable<void>;
  extends?: Theme;
  /**
   * Runs inside the root component's `setup()` (during SSR too). With
   * `extends`, setups run base-first, like `enhanceApp`.
   */
  setup?: () => void;
  /**
   * @deprecated Render not found page by checking `useData().page.value.isNotFound` in Layout instead.
   */
  NotFound?: Component;
}
//#endregion
export { EnhanceAppContext, Theme };